# int/float comparisons are exact (no rounding of the int), and int / int is correctly rounded
print(2 ** 53 + 1 > 2.0 ** 53, 2 ** 53 + 1 == 2.0 ** 53, 9007199254740993 == 9007199254740992.0, 2 ** 53 + 1 >= 2.0 ** 53 + 2)
print(10 ** 400 > 1e308, 10 ** 400 < float("inf"), -10 ** 400 < -1e308, 10 ** 23 == 1e23, 10 ** 22 == 1e22, max(2 ** 53 + 1, 2.0 ** 53))
print({2 ** 53 + 1: "a", 2.0 ** 53: "b"}, 2 ** 53 + 1 in [2.0 ** 53], 10 ** 22 in {1e22})
print(10 ** 400 / 10 ** 399, (2 ** 53 + 1) / 1, (2 ** 64 + 1) / 2, (10 ** 30 + 1) / 10 ** 15, (3 ** 50) / (2 ** 40), (2 ** 60 + 3) / 7)
print((10 ** 30) // 7, (10 ** 30) % 7, -(2 ** 64) // 3, -(2 ** 64) % 7, (2 ** 64) // -5, 2 ** 60 // 1.0, 10 ** 20 % 7.0)
